#![allow(clippy::type_complexity)]
//! Golden test: every noise router / aquifer function of every vanilla noise settings, for several seeds,
//! compared bit-for-bit against the vanilla server (fixture generated by `tests/oracle/RandomStateOracle.java`).

use std::collections::BTreeMap;
use std::path::PathBuf;
use std::sync::Arc;

use mc_core::ident::Identifier;
use mc_worldgen::data::{FsDataSource, WorldgenRegistries};
use mc_worldgen::densityfunction::{DensityBuffer, DensityFunction, DensityVolume, SamplerContext};
use mc_worldgen::noise_settings::NoiseGeneratorSettings;
use mc_worldgen::random_state::RandomState;

const VOLUMES: [[i32; 9]; 4] = [
    [5, 4, 5, -17, -12, 3, 1, 1, 1],
    [4, 6, 4, -16, -8, 32, 4, 8, 4],
    [1, 1, 1, 5, 37, -19, 1, 1, 1],
    [3, 5, 2, 2, 17, -6, 2, 3, 5],
];

fn data_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../ref/src/data")
}

fn functions(settings: &NoiseGeneratorSettings) -> BTreeMap<String, DensityFunction> {
    let r = &settings.noise_router;
    let mut fns = BTreeMap::new();
    fns.insert("temperature".to_string(), r.temperature.clone());
    fns.insert("vegetation".to_string(), r.vegetation.clone());
    fns.insert("continents".to_string(), r.continents.clone());
    fns.insert("erosion".to_string(), r.erosion.clone());
    fns.insert("depth".to_string(), r.depth.clone());
    fns.insert("ridges".to_string(), r.ridges.clone());
    fns.insert(
        "chunk_surface_level".to_string(),
        r.chunk_surface_level.clone(),
    );
    fns.insert("final_density".to_string(), r.final_density.clone());
    if let Some(a) = &settings.aquifers {
        fns.insert("aquifers.barrier".to_string(), a.barrier.clone());
        fns.insert(
            "aquifers.fluid_level_floodedness".to_string(),
            a.fluid_level_floodedness.clone(),
        );
        fns.insert(
            "aquifers.fluid_level_spread".to_string(),
            a.fluid_level_spread.clone(),
        );
        fns.insert("aquifers.lava".to_string(), a.lava.clone());
        fns.insert("aquifers.exclusion".to_string(), a.exclusion.clone());
        fns.insert(
            "aquifers.surface_level".to_string(),
            a.surface_level.clone(),
        );
    }
    fns
}

/// Router + aquifer functions of every vanilla noise settings.
#[test]
fn router_functions_match_vanilla() {
    check_fixture("random_state.txt", 30_000);
}

/// Every registered density function (caves, ore veins, ...) under overworld/nether/end random states.
#[test]
fn all_registered_density_functions_match_vanilla() {
    check_fixture("density_functions.txt", 10_000);
}

fn check_fixture(file: &str, min_samples: usize) {
    let fixture = std::fs::read_to_string(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures")
            .join(file),
    )
    .expect("fixture present");
    let registries = Arc::new(WorldgenRegistries::new(Arc::new(FsDataSource::new(
        data_root(),
    ))));

    type State = (
        (String, i64),
        RandomState,
        BTreeMap<String, DensityFunction>,
        SamplerContext,
    );
    let mut state: Option<State> = None;
    let (mut checked, mut mismatches) = (0usize, Vec::new());

    for line in fixture.lines() {
        let mut parts = line.split(' ');
        let kind = parts.next().unwrap();
        let setting = parts.next().unwrap().to_string();
        let seed: i64 = parts.next().unwrap().parse().unwrap();
        let name = parts.next().unwrap().to_string();

        if state.as_ref().map(|s| &s.0) != Some(&(setting.clone(), seed)) {
            let id = Identifier::with_default_namespace(&setting).unwrap();
            let settings = registries
                .noise_settings(&id)
                .unwrap_or_else(|e| panic!("{setting}: {e}"));
            let rs = RandomState::create(registries.clone(), seed, &settings);
            let fns = functions(&settings);
            let cached = SamplerContext::builder().enable_caches().build();
            state = Some(((setting.clone(), seed), rs, fns, cached));
        }
        let (_, rs, fns, cached) = state.as_ref().unwrap();
        let function = match name.strip_prefix("df:") {
            Some(id) => {
                registries
                    .density_function(&Identifier::parse(id).unwrap())
                    .unwrap()
                    .value
            }
            None => fns[&name].clone(),
        };
        let function = &function;
        let sampler = rs.get_sampler(function);

        match kind {
            "P" | "C" => {
                let x: i32 = parts.next().unwrap().parse().unwrap();
                let y: i32 = parts.next().unwrap().parse().unwrap();
                let z: i32 = parts.next().unwrap().parse().unwrap();
                let expected = u32::from_str_radix(parts.next().unwrap(), 16).unwrap();
                let actual = if kind == "P" {
                    rs.sample_block_value_uncached(function, x, y, z)
                } else {
                    sampler.sample_value(cached, x, y, z)
                }
                .to_bits();
                checked += 1;
                if actual != expected {
                    mismatches.push(format!(
                        "{kind} {setting} seed={seed} {name} ({x},{y},{z}): expected {} got {}",
                        f32::from_bits(expected),
                        f32::from_bits(actual)
                    ));
                }
            }
            "V" => {
                let v: usize = parts.next().unwrap().parse().unwrap();
                let n: usize = parts.next().unwrap().parse().unwrap();
                let d = VOLUMES[v];
                let volume =
                    DensityVolume::new(d[0], d[1], d[2], d[3], d[4], d[5], d[6], d[7], d[8]);
                assert_eq!(volume.size(), n);
                let mut buffer = DensityBuffer::create_unpooled(n);
                sampler.sample_volume(&SamplerContext::empty_uncached(), &mut buffer, &volume);
                for i in 0..n {
                    let expected = u32::from_str_radix(parts.next().unwrap(), 16).unwrap();
                    checked += 1;
                    if buffer.get(i).to_bits() != expected {
                        mismatches.push(format!(
                            "V {setting} seed={seed} {name} vol{v}[{i}]: expected {} got {}",
                            f32::from_bits(expected),
                            buffer.get(i)
                        ));
                    }
                }
            }
            other => panic!("unknown fixture line kind {other}"),
        }
    }

    assert!(
        checked > min_samples,
        "fixture unexpectedly small: {checked}"
    );
    assert!(
        mismatches.is_empty(),
        "{} of {checked} samples differ from vanilla; first: \n{}",
        mismatches.len(),
        mismatches
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

#[test]
fn random_state_is_shareable_across_threads() {
    fn assert_send_sync<T: Send + Sync>() {}
    assert_send_sync::<RandomState>();
    assert_send_sync::<DensityFunction>();
}
